library(haven)
library(dplyr)
library(tidyr)
library(purrr)
library(labelled)
library(readr)

# Define file paths
files <- list(
  wave1 = "data/input/wave_one_lsype_young_person_2020.tab",
  wave2 = "data/input/wave_two_lsype_young_person_2020.tab",
  wave4 = "data/input/wave_four_lsype_young_person_2020.tab",
  wave8_self = "data/input/ns8_2015_self_completion.tab",
  wave8_derived = "data/input/ns8_2015_derived.tab",
  wave9 = "data/input/ns9_2022_main_interview.tab",
  wave9_derived = "data/input/ns9_2022_derived_variables.tab"
)

# Load each file
wave1 <- read_delim(files$wave1, delim = "\t", show_col_types = FALSE)
wave2 <- read_delim(files$wave2, delim = "\t", show_col_types = FALSE)
wave4 <- read_delim(files$wave4, delim = "\t", show_col_types = FALSE)
wave8_self <- read_delim(files$wave8_self, delim = "\t", show_col_types = FALSE)
wave8_derived <- read_delim(files$wave8_derived, delim = "\t", show_col_types = FALSE)
wave9 <- read_delim(files$wave9, delim = "\t", show_col_types = FALSE)
wave9_derived <- read_delim(files$wave9_derived, delim = "\t", show_col_types = FALSE)

# Merge all datasets by NSID
merged <- full_join(wave1, wave2, by = "NSID")
merged <- full_join(merged, wave4, by = "NSID")
merged <- full_join(merged, wave8_self, by = "NSID")
merged <- full_join(merged, wave8_derived, by = "NSID")
merged <- full_join(merged, wave9, by = "NSID")
merged <- full_join(merged, wave9_derived, by = "NSID")

# Define GHQ-12 item names for each wave
ghq_items_wave2 <- c(
  "W2concenYP", "W2nosleepYP", "W2usefulYP", "W2decideYP", "W2strainYP", "W2difficYP",
  "W2activYP", "W2probsYP", "W2depressYP", "W2noconfYP", "W2wthlessYP", "W2happyYP"
)

ghq_items_wave4 <- c(
  "W4ConcenYP", "W4NoSleepYP", "W4UsefulYP", "W4DecideYP", "W4StrainYP", "W4DifficYP",
  "W4ActivYP", "W4ProbsYP", "W4DepressYP", "W4NoConfYP", "W4WthlessYP", "W4HappyYP"
)

ghq_items_wave8 <- c(
  "W8GHQ12_1", "W8GHQ12_2", "W8GHQ12_3", "W8GHQ12_4", "W8GHQ12_5", "W8GHQ12_6",
  "W8GHQ12_7", "W8GHQ12_8", "W8GHQ12_9", "W8GHQ12_10", "W8GHQ12_11", "W8GHQ12_12"
)

ghq_items_wave9 <- c(
  "W9GHQ12_1", "W9GHQ12_2", "W9GHQ12_3", "W9GHQ12_4", "W9GHQ12_5", "W9GHQ12_6",
  "W9GHQ12_7", "W9GHQ12_8", "W9GHQ12_9", "W9GHQ12_10", "W9GHQ12_11", "W9GHQ12_12"
)

# Function to convert negative codes to standard missing values
convert_missing <- function(x) {
  x[x %in% c(-999, -998, -997, -995)] <- -2
  x[x == -99] <- -3
  x[x == -97] <- -1
  x[x == -96] <- -3
  x[x == -94] <- -8
  x[x == -92] <- -9
  x[x == -91] <- -1
  x[x == -9] <- -9
  x[x == -8] <- -8
  x[x == -3] <- -3
  x[x == -1] <- -1
  return(x)
}

# Function to sum GHQ items for item-summed score (ghqtl)
sum_ghq_items <- function(item_values) {
  # Check if all values are non-negative (>= 0)
  if (any(is.na(item_values))) {
    return(NA)
  }
  if (any(item_values < 0)) {
    return(NA)
  }
  return(sum(item_values))
}

# Function to calculate GHQ caseness (0-12) using standard 0-1-2-2 scoring
# Items 1-6 (negatively worded): 1,2 -> 0; 3,4 -> 1
# Items 7-12 (positively worded): 1,2 -> 1; 3,4 -> 0
calc_caseness <- function(item_values) {
  if (any(is.na(item_values))) {
    return(NA)
  }
  if (any(item_values < 0)) {
    return(NA)
  }

  # For each item, determine the caseness score
  scores <- rep(0, 12)
  for (i in 1:12) {
    val <- item_values[i]
    if (val <= 6) {
      # Negative items: 1,2 -> 0; 3,4 -> 1
      scores[i] <- ifelse(val >= 3, 1, 0)
    } else {
      # Positive items (7-12): 1,2 -> 1; 3,4 -> 0
      scores[i] <- ifelse(val <= 2, 1, 0)
    }
  }
  return(sum(scores))
}

# Process each wave's GHQ items and create output variables
# Age 15 (wave 2)
merged <- merged %>%
  mutate(
    ghq15_raw = case_when(
      all(!is.na(select(., all_of(ghq_items_wave2)))) ~ 0,
      TRUE ~ NA_real_
    ),
    ghq15_caseness = case_when(
      all(!is.na(select(., all_of(ghq_items_wave2)))) ~ {
        items <- as.numeric(select(., all_of(ghq_items_wave2)))
        calc_caseness(items)
      },
      TRUE ~ NA_real_
    ),
    ghqtl15 = case_when(
      all(!is.na(select(., all_of(ghq_items_wave2))) & 
          all(select(., all_of(ghq_items_wave2)) >= 0)) ~ {
        sum(select(., all_of(ghq_items_wave2)))
      },
      TRUE ~ NA_real_
    )
  )

# Age 17 (wave 4)
merged <- merged %>%
  mutate(
    ghq17_caseness = case_when(
      all(!is.na(select(., all_of(ghq_items_wave4)))) ~ {
        items <- as.numeric(select(., all_of(ghq_items_wave4)))
        calc_caseness(items)
      },
      TRUE ~ NA_real_
    ),
    ghqtl17 = case_when(
      all(!is.na(select(., all_of(ghq_items_wave4))) & 
          all(select(., all_of(ghq_items_wave4)) >= 0)) ~ {
        sum(select(., all_of(ghq_items_wave4)))
      },
      TRUE ~ NA_real_
    )
  )

# Age 25 (wave 8)
merged <- merged %>%
  mutate(
    ghq25_caseness = case_when(
      all(!is.na(select(., all_of(ghq_items_wave8)))) ~ {
        items <- as.numeric(select(., all_of(ghq_items_wave8)))
        calc_caseness(items)
      },
      TRUE ~ NA_real_
    ),
    ghqtl25 = case_when(
      all(!is.na(select(., all_of(ghq_items_wave8))) & 
          all(select(., all_of(ghq_items_wave8)) >= 0)) ~ {
        sum(select(., all_of(ghq_items_wave8)))
      },
      TRUE ~ NA_real_
    )
  )

# Age 32 (wave 9)
merged <- merged %>%
  mutate(
    ghq32_caseness = case_when(
      all(!is.na(select(., all_of(ghq_items_wave9)))) ~ {
        items <- as.numeric(select(., all_of(ghq_items_wave9)))
        calc_caseness(items)
      },
      TRUE ~ NA_real_
    ),
    ghqtl32 = case_when(
      all(!is.na(select(., all_of(ghq_items_wave9))) & 
          all(select(., all_of(ghq_items_wave9)) >= 0)) ~ {
        sum(select(., all_of(ghq_items_wave9)))
      },
      TRUE ~ NA_real_
    )
  )

# Create final output with only GHQ variables
output <- merged %>%
  select(NSID, ghqtl15, ghq15_caseness, ghqtl17, ghq17_caseness, 
         ghqtl25, ghq25_caseness, ghqtl32, ghq32_caseness)

# Rename caseness variables to match requirements
names(output)[names(output) == "ghq15_caseness"] <- "ghq15"
names(output)[names(output) == "ghq17_caseness"] <- "ghq17"
names(output)[names(output) == "ghq25_caseness"] <- "ghq25"
names(output)[names(output) == "ghq32_caseness"] <- "ghq32"

# Write output
write_csv(output, "data/output/cleaned_data.csv")

cat("Output written successfully.\n")
cat("Rows:", nrow(output), "\n")
cat("Columns:", ncol(output), "\n")

